program.source:
Subroutine CobrarConIva(total As Integer By Reference)
  total <- total + total * 18 Div 100;
  total <- total - total Div 10;
  Write "Total: ", total;
EndSubroutine

Algorithm Caja
  Define compra As Integer;
  Read compra;
  CobrarConIva(compra);
EndAlgorithm

